/**
 * Channel packs: Slack app setup, and webhook replay, forward, and events
 * helpers for GitHub, GitLab, Bitbucket, and PagerDuty. Each subcommand is
 * its own command, and each calls the pack's dispatcher with its name.
 */
import { basename, resolve } from "node:path";
import { slugFromDirectoryName } from "../../slug.js";
import { defineCommand } from "../command.js";
import { apiKeyFlag, dirFlag, dryRunFlag, jsonFlag, printAliasFlag, slugFlag, teamFlag, yesFlag, } from "../flags.js";
import { parsePort } from "./serve.js";
/** Where a webhook helper finds the served agent and its channels. */
const forgeTargetFlags = {
    ...dirFlag,
    ...slugFlag,
    channel: {
        type: "string",
        value: "<id>",
        description: "Use only this channel id when several are declared.",
    },
    host: {
        type: "string",
        value: "<host>",
        description: "Host of the served agent (default 127.0.0.1).",
    },
    port: { type: "string", value: "<n>", description: "Port of the served agent (default 3000)." },
    url: {
        type: "string",
        value: "<url>",
        kind: "url",
        description: "Post to this base URL (for example a tunnel) instead of host:port.",
    },
    ...jsonFlag,
};
const forgeReplayFlags = {
    ...forgeTargetFlags,
    events: {
        type: "string",
        value: "<a,b,c|*>",
        description: "Events to synthesize. `*` means every event the channel declares.",
    },
    secret: {
        type: "string",
        value: "<secret>",
        description: "Webhook signing secret (defaults to the pack's *_WEBHOOK_SECRET variable).",
    },
    comment: { type: "string", value: "<text>", description: "Comment or note body." },
    "dry-run": { type: "boolean", description: "Print the synthesized payloads. Post nothing." },
    "fixtures-dir": {
        type: "string",
        value: "<dir>",
        kind: "outputPath",
        description: "Write the synthesized payloads here as fixtures.",
    },
    out: {
        type: "string",
        hidden: true,
        kind: "outputPath",
        description: "Older spelling of --fixtures-dir.",
    },
};
function forgeTarget(values) {
    return {
        dir: values.dir,
        slug: values.slug,
        channel: values.channel,
        host: values.host,
        port: parsePort(values.port),
        url: values.url,
        json: values.json,
    };
}
function forgeReplay(values) {
    return {
        ...forgeTarget(values),
        events: values.events,
        secret: values.secret,
        comment: values.comment,
        dryRun: values["dry-run"],
        out: values["fixtures-dir"] ?? values.out,
    };
}
const servingNote = "Needs the agent already serving (`agent-sdk dev` or `agent-sdk serve --dev`).";
// ---------------------------------------------------------------- GitHub --
export const githubForwardCommand = defineCommand({
    name: "github forward",
    group: "other",
    parentSummary: "GitHub webhook pack: forward live deliveries, replay a PR, list events.",
    summary: "Forward live GitHub webhooks to the served githubChannel()s (gh webhook forward).",
    description: `
Derives the URL and events per channel and infers the repo from the git remote.
One forwarder fans out to every matching channel (GitHub allows one forwarder
per repo). Needs repo admin (org owner for --org) and the gh CLI login: a
GITHUB_TOKEN or GH_TOKEN override makes deliveries fail with 401. ${servingNote}`,
    flags: {
        ...forgeTargetFlags,
        repo: { type: "string", value: "<owner/repo>", description: "Repository to forward from." },
        org: { type: "string", value: "<org>", description: "Organization login (org-level hooks)." },
        events: {
            type: "string",
            value: "<a,b,c>",
            description: "Override the derived webhook event list.",
        },
        secret: {
            type: "string",
            value: "<secret>",
            description: "Webhook signing secret (defaults to GITHUB_WEBHOOK_SECRET).",
        },
        install: { type: "boolean", description: "Install the cli/gh-webhook extension if missing." },
    },
    effect: "interactive",
    async run({ values }) {
        const { cmdGithub } = await import("../../cli-github.js");
        return cmdGithub("forward", {
            ...forgeTarget(values),
            repo: values.repo,
            org: values.org,
            events: values.events,
            secret: values.secret,
            install: values.install,
        });
    },
});
export const githubReplayCommand = defineCommand({
    name: "github replay",
    group: "other",
    summary: "Replay webhook payloads synthesized from a pull request you can read.",
    description: `
Reads the PR with \`gh api\` (pull access is enough; no admin, no relay), builds
GitHub-shaped payloads for --events (default pull_request), signs them, and
posts them to the matching channels. ${servingNote}`,
    args: [{ name: "pr", description: "PR URL or owner/repo#N.", required: true }],
    flags: {
        ...forgeReplayFlags,
        action: { type: "string", value: "<action>", description: "Event action, such as opened." },
        conclusion: {
            type: "string",
            value: "<conclusion>",
            description: "CI conclusion for check_run, check_suite, and status.",
        },
        context: { type: "string", value: "<context>", description: "Commit-status context." },
    },
    effect: "write",
    examples: ["agent-sdk github replay https://github.com/o/r/pull/12 --events '*' --dry-run"],
    async run({ values, positionals }) {
        const { cmdGithub } = await import("../../cli-github.js");
        return cmdGithub("replay", {
            ...forgeReplay(values),
            prUrl: positionals[0],
            action: values.action,
            conclusion: values.conclusion,
            context: values.context,
        });
    },
});
export const githubEventsCommand = defineCommand({
    name: "github events",
    group: "other",
    summary: "List the discovered GitHub channels and the webhook events each accepts.",
    flags: forgeTargetFlags,
    effect: "read",
    async run({ values }) {
        const { cmdGithub } = await import("../../cli-github.js");
        return cmdGithub("events", forgeTarget(values));
    },
});
export const githubDoctorCommand = defineCommand({
    name: "github doctor",
    group: "other",
    summary: "Check gh, its auth, and the cli/gh-webhook extension.",
    flags: {
        install: { type: "boolean", description: "Install the cli/gh-webhook extension if missing." },
        ...jsonFlag,
    },
    effect: "read",
    async run({ values }) {
        const { cmdGithub } = await import("../../cli-github.js");
        return cmdGithub("doctor", { dir: ".", install: values.install, json: values.json });
    },
});
// ---------------------------------------------------------------- GitLab --
export const gitlabReplayCommand = defineCommand({
    name: "gitlab replay",
    group: "other",
    parentSummary: "GitLab webhook pack: replay a merge request, list events, forward recipe.",
    summary: "Replay webhook payloads synthesized from a merge request you can read.",
    description: `
Reads the MR over the REST API with GITLAB_TOKEN (read_api; Reporter access is
enough). Self-managed GitLab also needs GITLAB_API_BASE_URL or a full MR URL.
Default event: merge_request. Sets X-Gitlab-Token from --secret or
GITLAB_WEBHOOK_SECRET. ${servingNote}`,
    args: [{ name: "mr", description: "MR URL or group/project!N.", required: true }],
    flags: {
        ...forgeReplayFlags,
        action: { type: "string", value: "<action>", description: "Event action, such as open." },
        conclusion: {
            type: "string",
            value: "<status>",
            description: "Pipeline status, such as success or failed.",
        },
    },
    effect: "write",
    async run({ values, positionals }) {
        const { cmdGitlab } = await import("../../cli-gitlab.js");
        return cmdGitlab("replay", {
            ...forgeReplay(values),
            mrUrl: positionals[0],
            action: values.action,
            conclusion: values.conclusion,
        });
    },
});
